const items = $input.all();
if (!items || items.length === 0) return [];

return items.map((itemObj) => {
  const item = itemObj.json;
  const id = item.id || item.threadId || `email-${Date.now()}`;
  const title = item.subject || item.snippet || item.title || '(No Subject)';
  const sender = typeof item.from === 'string'
    ? item.from
    : (item.from?.value?.[0]?.address || item.sender || 'Unknown Sender');
  const originalContent = item.snippet || item.text || item.body || item.originalContent || title;
  const eventCreatedAt = item.internalDate
    ? new Date(parseInt(item.internalDate)).toISOString()
    : (item.date ? new Date(item.date).toISOString() : new Date().toISOString());
  const sourceUrl = `https://mail.google.com/mail/u/0/#all/${item.threadId || id}`;

  return {
    json: {
      externalId: id,
      threadId: item.threadId || id,
      title,
      sender,
      originalContent,
      eventCreatedAt,
      sourceUrl
    }
  };
});

