parameters.jsCode:
const email = $('Normalize Email').first().json;
let summary = 'Email summary received.';

try {
  const input = $input.first().json;
  const text = input.text || input.candidates?.[0]?.content?.parts?.[0]?.text || '';
  if (text) {
    const cleaned = text.replace(/```json|```/g, '').trim();
    const parsed = JSON.parse(cleaned);
    summary = parsed.summary || text;
  }
} catch (e) {
  summary = email.originalContent.slice(0, 150) + '...';
}

return [{
  json: {
    source: 'gmail',
    activity_type: 'email',
    external_id: email.externalId,
    title: email.title,
    sender: email.sender,
    summary,
    original_content: email.originalContent,
    source_url: email.sourceUrl,
    event_created_at: email.eventCreatedAt,
    metadata: { thread_id: email.threadId, subject: email.title }
  }
}];
